// Some portions generated by Claude

// Plan task M13.6 (user request): every warning and error the Workbench shows is one callout component, aligned and
// padded the same way, in light and dark mode, at desktop and phone widths.
// @ts-check
const fs = require('node:fs');
const path = require('node:path');
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-warnings');
const SHOTS = process.env.WORKBENCH_WARNING_SHOTS || '';


test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID, { graphs: ['spl'] });
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

/** Every visible callout on the page, measured. */
function measureCallouts(page) {
	return page.evaluate(() => Array.from(document.querySelectorAll('.workbench-callout')).filter((callout) => {
		const box = callout.getBoundingClientRect();
		return box.width > 0 && box.height > 0 && !callout.closest('[hidden], #workbench-kept-alive');
	}).map((callout) => {
		const style = getComputedStyle(callout);
		const icon = callout.querySelector('.workbench-callout__icon');
		const body = callout.querySelector('.workbench-callout__body');
		const range = document.createRange();
		range.selectNodeContents(body);
		const line = Array.from(range.getClientRects()).filter((rect) => rect.width > 0 && rect.height > 0)[0];
		const iconBox = icon ? icon.getBoundingClientRect() : null;
		const box = callout.getBoundingClientRect();
		const card = callout.parentElement.closest('.workbench-island, .workbench-form-card, .query-output, dialog, '
			+ '.workbench-page-surface');
		const cardBox = card.getBoundingClientRect();
		const cardStyle = getComputedStyle(card);
		return {
			text: callout.textContent.trim().slice(0, 60),
			kind: callout.className,
			iconOffset: iconBox && line ? Math.abs((iconBox.top + iconBox.height / 2) - (line.top + line.height / 2)) : null,
			iconLeft: iconBox ? iconBox.left - box.left : null,
			padding: [style.paddingTop, style.paddingRight, style.paddingBottom, style.paddingLeft],
			borderRadius: style.borderTopLeftRadius,
			leftInset: box.left - (cardBox.left + parseFloat(cardStyle.borderLeftWidth)),
			rightInset: (cardBox.right - parseFloat(cardStyle.borderRightWidth)) - box.right,
			overflow: callout.scrollWidth - callout.clientWidth,
			pageOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth
		};
	}));
}

/** One callout component everywhere: icon on the first line, the component's padding, inside its card. */
async function expectAlignedCallouts(page, label, minimum = 1) {
	const callouts = await measureCallouts(page);
	expect(callouts.length, `${label}: callouts shown`).toBeGreaterThanOrEqual(minimum);
	for (const callout of callouts) {
		const name = `${label}: "${callout.text}"`;
		expect.soft(callout.iconOffset, `${name}: icon centred on the first line`).not.toBeNull();
		expect.soft(callout.iconOffset, `${name}: icon centred on the first line`).toBeLessThanOrEqual(2);
		expect.soft(callout.iconLeft, `${name}: icon at the start padding`).toBeCloseTo(15, 0);
		expect.soft(callout.padding, `${name}: component padding`).toEqual(['12px', '14px', '12px', '14px']);
		expect.soft(callout.borderRadius, `${name}: component radius`).toBe('7px');
		expect.soft(callout.leftInset, `${name}: inside its card on the left`).toBeGreaterThanOrEqual(0);
		expect.soft(callout.rightInset, `${name}: inside its card on the right`).toBeGreaterThanOrEqual(-0.5);
		expect.soft(callout.overflow, `${name}: no overflow`).toBeLessThanOrEqual(0);
		expect.soft(callout.pageOverflow, `${name}: no page overflow`).toBeLessThanOrEqual(1);
	}
	return callouts;
}

async function capture(page, name) {
	if (!SHOTS) {
		return;
	}
	fs.mkdirSync(SHOTS, { recursive: true });
	await page.screenshot({ path: path.join(SHOTS, `${name}.png`), fullPage: true, animations: 'disabled' });
}

const VARIANTS = [
	{ name: 'desktop-light', viewport: { width: 1440, height: 900 }, colorScheme: 'light' },
	{ name: 'desktop-dark', viewport: { width: 1440, height: 900 }, colorScheme: 'dark' },
	{ name: 'mobile-light', viewport: { width: 390, height: 844 }, colorScheme: 'light' }
];

for (const variant of VARIANTS) {
	test.describe(variant.name, () => {
		test.use({ viewport: variant.viewport, colorScheme: variant.colorScheme });

		test('page warnings: Clear, Remove and a Remove without values', async ({ page }) => {
			await page.goto(repositoryPageUrl(REPOSITORY_ID, 'clear'));
			await waitForRoute(page, 'clear');
			await expectAlignedCallouts(page, 'Clear');
			await capture(page, `${variant.name}-clear`);

			await page.goto(repositoryPageUrl(REPOSITORY_ID, 'remove'));
			await waitForRoute(page, 'remove');
			await expectAlignedCallouts(page, 'Remove');
			await capture(page, `${variant.name}-remove`);

			// The browser posts the empty form itself, as an old client would (plan task M6.1).
			await page.locator('#remove-form').evaluate((form) => form.submit());
			await expect(page.locator('#remove-form .workbench-callout--error')).toBeVisible();
			await expectAlignedCallouts(page, 'Remove without values', 2);
			await capture(page, `${variant.name}-remove-error`);
		});

		test('page errors: Update, Add, Explore and a page that cannot be loaded', async ({ page }) => {
			await page.goto(repositoryPageUrl(REPOSITORY_ID, 'update'));
			await waitForRoute(page, 'update');
			await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.setValue('INSERT {'));
			await page.locator('#update-form input[type="submit"]').click();
			await expect(page.locator('[id="updateString.errors"]')).toBeVisible();
			await expectAlignedCallouts(page, 'Update');
			await capture(page, `${variant.name}-update-error`);

			await page.goto(repositoryPageUrl(REPOSITORY_ID, 'add'));
			await waitForRoute(page, 'add');
			await page.locator('label[for="source-url"]').click();
			await page.locator('#url').fill('not a valid URL');
			await page.locator('form[enctype="multipart/form-data"] input[type="submit"][value="Upload"]').click();
			await expect(page.locator('.workbench-callout--error')).toBeVisible();
			await expectAlignedCallouts(page, 'Add');
			await capture(page, `${variant.name}-add-error`);

			// A page whose answer is an error, opened directly: the shell shows the error.
			await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent('"unterminated')}`);
			await expect(page.locator('#workbench-app [role="alert"]').first()).toBeVisible();
			await expectAlignedCallouts(page, 'Explore');
			// The error is the page: no empty card around it.
			const surface = await page.locator('#workbench-page-surface').boundingBox();
			const error = await page.locator('#workbench-page-surface > .workbench-callout').boundingBox();
			expect(surface.height - error.height, 'the error page has no empty card around its callout').toBeLessThanOrEqual(1);
			await capture(page, `${variant.name}-explore-error`);
		});

		test('query result states: no query and a syntax error', async ({ page }) => {
			await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
			await waitForRoute(page, 'query');
			await page.locator('#exec').click();
			await expect(page.locator('#query-results .workbench-callout')).toBeVisible();
			await expectAlignedCallouts(page, 'Query without text');
			await capture(page, `${variant.name}-query-empty`);

			await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.setValue('SELECT WHERE {'));
			await page.locator('#exec').click();
			await expect(page.locator('#query-results .workbench-callout--error')).toBeVisible();
			await expectAlignedCallouts(page, 'Query syntax error');
			await capture(page, `${variant.name}-query-error`);
		});
	});
}
